TEXTS['values-en-rUS'] = TEXTS['values']

def write_texts(texts=TEXTS):
    import json
    catalog_path = Path(__file__).with_name('catalog.json')
    catalog = json.loads(catalog_path.read_text(encoding='utf-8'))
    from generate import qualifier
    for key in KEYS:
        if key not in catalog['keys']:
            catalog['keys'].append(key)
            for values in catalog['locales'].values():
                values.append('')
    for locale, values in catalog['locales'].items():
        translations = texts['values-' + qualifier(locale)]
        assert len(translations) == len(KEYS), locale
        for key, value in zip(KEYS, translations):
            values[catalog['keys'].index(key)] = value
    catalog_path.write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    import subprocess, sys
    subprocess.run([sys.executable, str(Path(__file__).with_name('generate.py'))], check=True)

if __name__ == '__main__':
    write_texts()
